def generate(seed):
    r = random.Random(seed)
    def isp(x):
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    while True:
        p = r.randrange(10000, 1000000)
        if isp(p):
            break
    while True:
        g = r.randrange(2, p - 1)
        x = r.randrange(2, p - 1)
        h = pow(g, x, p)
        if h != 1 and h != g and h != 0:
            return str(g) + ' ' + str(h) + ' ' + str(p)

