def solve(clue):
    g, h, p = [int(t) for t in clue.split()]
    m = int(p ** 0.5) + 1
    tbl = {}
    e = 1
    for j in range(m):
        if e not in tbl:
            tbl[e] = j
        e = e * g % p
    gm = pow(pow(g, p - 2, p), m, p)
    y = h
    for i in range(m + 2):
        if y in tbl:
            return str(i * m + tbl[y])
        y = y * gm % p
    return ''

